def seed_institutions():
    categories_needed = [
        'Public University', 'Private University', 'University College',
        'National Polytechnic', 'Technical Training Institute',
        'Technical and Vocational College', 'Specialised Training Institution',
        'Other Recognised Institution'
    ]
    for cat_name in categories_needed:
        if not InstitutionCategory.query.filter_by(name=cat_name).first():
            db.session.add(InstitutionCategory(name=cat_name))
    db.session.commit()

    added = 0
    for inst_data in INSTITUTIONS:
        existing = Institution.query.filter(
            db.func.lower(Institution.name) == inst_data['name'].lower()
        ).first()
        if existing:
            continue
        cat = InstitutionCategory.query.filter_by(name=inst_data['category']).first()
        inst = Institution(
            name=inst_data['name'],
            abbreviation=inst_data.get('abbreviation'),
            category_id=cat.id if cat else None,
            ownership=inst_data.get('ownership', 'Public'),
            county=inst_data.get('county'),
            town=inst_data.get('town'),
            website=inst_data.get('website'),
            source=inst_data.get('source')
        )
        db.session.add(inst)
        db.session.flush()  # get inst.id
        community = InstitutionCommunity(institution_id=inst.id)
        db.session.add(community)
        added += 1
    db.session.commit()
    print(f"{added} institutions added.")
